set deathReportId = pInput.deathReportid set empi = pInput.empi set lastName = pInput.name.lastName set firstName = pInput.name.firstName set middleName = pInput.name.middleName set street = pInput.address.street1 set city = pInput.address.city set state = pInput.state set zip = pInput.zip set dateOfBirth = pInput.dob set gender = pInput.gender set race = pInput.race set ethnicity = pInput.ethnicity set dateOfDeath = pInput.dod
