set tSeg1 = ##class(EnsLib.HL7.Segment).ImportFromString("MSH|^~\&|Utah Department of Health|ENSEMBLE|||||ADT^A31|||2.3.1|||||||||") set tSeg2 = ##class(EnsLib.HL7.Segment).ImportFromString("EVN|A31|200811241212||1||") set tSeg3 = ##class(EnsLib.HL7.Segment).ImportFromString("PID|||"_empi_"||"_lastName_"^"_firstName_"^"_middleName_"||"_dateOfBirth_"|"_gender_"||"_race_"|"_street_"^"_city_"^"_state_"^"_zip_"||||||||||||||||||||"_dateOfDeath_"|Y"_"|||||||") set tSeg4 = ##class(EnsLib.HL7.Segment).ImportFromString("PV1||||")
set tsc = pHL7.SetSegmentAt(tSeg1,1) set tsc = pHL7.InsertSegmentAt(tSeg2,2) set tsc = pHL7.InsertSegmentAt(tSeg3,3) set tsc = pHL7.InsertSegmentAt(tSeg4,4)
// Send to MsgRouter for processing do ..SendRequestAsync("Utah-Demogr_Cern-Demogr-Hl7-UTDEATHDATE1", pHL7)
